using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using CosmicBlock.UI;
using CosmicBlock.Core;
using CosmicBlock.Blocks;
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
public static class HomeMenuMeshProbe {
 static double began;static int frames,count;static string errors="",warnings="";static GameFlowController flow;static GameSession session;static Dictionary<string,int> saved=new Dictionary<string,int>();static List<string> keys=new List<string>(),results=new List<string>();
 public static void Run(){RunSaveStore.PathOverride=Path.GetFullPath("Validation/home-menu-isolated.json");keys.Add(GameSession.DefaultBestScoreKey);keys.Add(PlanetSelection.Key);keys.Add(PlanetRestoration.VersionKey);foreach(var d in PlanetDefinitions.All){keys.Add(d.EnergyKey);keys.Add(d.UnlockKey);keys.Add(PlanetCompletionNotice.Key(d.Id));}foreach(var k in keys){if(PlayerPrefs.HasKey(k))saved[k]=PlayerPrefs.GetInt(k);PlayerPrefs.DeleteKey(k);}PlayerPrefs.SetInt(PlanetRestoration.VersionKey,2);PlayerPrefs.SetInt(PlanetRestoration.DefaultKey,1500);PlayerPrefs.SetInt(GameSession.DefaultBestScoreKey,19000);PlayerPrefs.Save();EditorSceneManager.OpenScene("Assets/Scenes/Game.unity");began=EditorApplication.timeSinceStartup;Application.logMessageReceived+=Log;EditorApplication.update+=Check;EditorApplication.EnterPlaymode();}
 static void Check(){if(EditorApplication.timeSinceStartup-began>240){Finish(false,"timeout");return;}if(!EditorApplication.isPlaying||++frames<40)return;EditorApplication.update-=Check;RunSaveStore.PathOverride=Path.GetFullPath("Validation/home-menu-isolated.json");RunSaveStore.Delete();flow=UnityEngine.Object.FindAnyObjectByType<GameFlowController>();session=UnityEngine.Object.FindAnyObjectByType<GameSession>();flow.ShowHome();flow.RefreshHome();session.StartCoroutine(Guard());}
 static IEnumerator Guard(){var tests=Tests();while(true){object value;try{if(!tests.MoveNext())break;value=tests.Current;}catch(Exception e){Finish(false,e.ToString());yield break;}yield return value;}Finish(errors.Length==0&&warnings.Length==0,errors+warnings);}
 static IEnumerator Tests(){var home=flow.HomeRoot.transform;var controls=home.GetComponent<HomeRunControls>();Req(Label("MainActions/GameStartButton/MeshPrimaryLabel").text=="게임 시작","저장 없으면 게임 시작");foreach(int h in new[]{1920,2400,1440})Capture(h,"fresh");
  home.Find("MainActions/GameStartButton").GetComponent<Button>().onClick.Invoke();Req(flow.Screen==FlowScreen.Game,"기존 PLAY 이벤트");session.DebugPrepareNextRow();Req(session.TryPlacePiece(session.Slots[0],3,3),"배치/클리어");session.DebugCompleteTurnForProbe();flow.RequestHome();flow.ConfirmHome();yield return null;Req(flow.HasSavedRun&&Label("MainActions/GameStartButton/MeshPrimaryLabel").text=="이어하기","HOME 이어하기 표시");var before=File.ReadAllText(RunSaveStore.SavePath);foreach(int h in new[]{1920,2400,1440})Capture(h,"resume");
  home.Find("MainActions/PlanetCollectionButton").GetComponent<Button>().onClick.Invoke();Req(flow.Screen==FlowScreen.Collection,"도감 진입");flow.ReturnFromCollection();Req(flow.Screen==FlowScreen.Home,"도감 HOME 복귀");Req(File.ReadAllText(RunSaveStore.SavePath)==before,"도감에서 Run 유지");
  home.Find("BottomActions/SettingsButton").GetComponent<Button>().onClick.Invoke();Req(flow.HomeView.SettingsVisible,"설정 이벤트");flow.HomeView.CloseSettings();home.Find("BottomActions/QuitButton").GetComponent<Button>().onClick.Invoke();Req(flow.HomeView.QuitVisible,"종료 확인 이벤트");flow.HomeView.CancelQuit();Req(!flow.HomeView.QuitVisible&&File.ReadAllText(RunSaveStore.SavePath)==before,"종료 취소 저장 유지");
  home.Find("NewGameButton").GetComponent<Button>().onClick.Invoke();Req(controls.NewGameVisible,"새 게임 확인");controls.CancelNewGame();Req(File.ReadAllText(RunSaveStore.SavePath)==before,"새 게임 취소 데이터 보존");home.Find("MainActions/GameStartButton").GetComponent<Button>().onClick.Invoke();Req(flow.Screen==FlowScreen.Game&&session.Score==110&&session.Combo==1,"이어하기 SCORE/Combo 유지");flow.ShowHome();controls.RequestNewGame();controls.ConfirmNewGame();Req(session.Score==0&&session.Combo==0&&session.State==GameState.Playing,"명시적 새 게임 기존 초기화");Req(session.BestScore==19000&&session.Restoration.CurrentEnergy==1500,"BEST/행성 보존");results.Add("PASS PLAY/이어하기/새 게임/도감/설정/종료 취소 및 저장 보존");
 }
 static TextMeshProUGUI Label(string p)=>flow.HomeRoot.transform.Find(p).GetComponent<TextMeshProUGUI>();
 static void Capture(int h,string state){var home=(RectTransform)flow.HomeRoot.transform;var canvas=GameObject.Find("GameCanvas").GetComponent<Canvas>();var safe=(RectTransform)home.parent;var sa=safe.GetComponent<SafeArea>();var cam=Camera.main;var rt=new RenderTexture(1080,h,24);var mode=canvas.renderMode;var camera=canvas.worldCamera;var target=cam.targetTexture;var active=RenderTexture.active;bool enabled=sa.enabled,ortho=cam.orthographic;float size=cam.orthographicSize;var min=safe.anchorMin;var max=safe.anchorMax;Texture2D tex=null;
  try{sa.enabled=false;rt.Create();cam.targetTexture=rt;cam.orthographic=true;cam.orthographicSize=h/2f;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=10;safe.anchorMin=h==2400?new Vector2(.02f,.04f):Vector2.zero;safe.anchorMax=h==2400?new Vector2(.98f,.94f):Vector2.one;safe.offsetMin=safe.offsetMax=Vector2.zero;Canvas.ForceUpdateCanvases();home.GetComponent<HomeFinalLayout>().Apply();home.GetComponent<HomeMenuMeshLayout>().SendMessage("LateUpdate");Canvas.ForceUpdateCanvases();
   var bg=(RectTransform)home.Find("HomeBackground");var sprite=bg.GetComponent<Image>().sprite;var full=(RectTransform)canvas.transform;bg.sizeDelta=sprite.rect.size*Mathf.Max(full.rect.width/sprite.rect.width,full.rect.height/sprite.rect.height);bg.anchoredPosition=home.InverseTransformPoint(full.TransformPoint(full.rect.center));
   Req(home.Find("TitleArea/Title").GetComponent<Image>().sprite.name=="home_title_starlight_block","로고 유지");Req(home.Find("HeroArea/HeroPlanet").GetComponent<Image>().sprite.name=="home_planet_hero","행성 유지");var paths=new[]{"MainActions/GameStartButton","MainActions/PlanetCollectionButton","BestScoreArea","BottomActions/SettingsButton","BottomActions/QuitButton","NewGameButton"};var bounds=World(safe);var rectangles=new List<Rect>();
   foreach(string path in paths){var r=(RectTransform)home.Find(path);Req(Inside(bounds,World(r)),"SafeArea "+path+" "+h);Req(!World(r).Overlaps(World((RectTransform)home.Find("DevButton"))),"DEV 겹침 없음 "+path);foreach(var prior in rectangles)Req(!prior.Overlaps(World(r)),"메뉴 겹침 없음 "+path);rectangles.Add(World(r));if(path!="BestScoreArea"&&path!="NewGameButton"){var button=r.GetComponent<Button>();Req(button.targetGraphic is HomeQuitMeshGraphic&&button.targetGraphic.raycastTarget,"메시 Hit "+path);Req(button.GetComponent<Image>().color.a==0,"PNG 표시 안 함");Req(r.GetComponentInChildren<HomeMenuIconGraphic>().canvasRenderer!=null,"메시 아이콘");}}
   Req(World((RectTransform)home.Find("MainActions/GameStartButton")).yMax<World((RectTransform)home.Find("HeroArea")).yMin,"Hero 간격 유지");Req(World((RectTransform)home.Find(paths[0])).width==World((RectTransform)home.Find(paths[1])).width,"CTA 폭 통일");
   var value=Label("BestScoreArea/Frame/MeshBestValue");foreach(int v in new[]{0,19000,999999,int.MaxValue}){value.text=v.ToString("N0");value.ForceMeshUpdate();Req(!value.isTextOverflowing,"BEST 최대값 "+v+" "+h);}home.GetComponent<HomeMenuMeshLayout>().SendMessage("LateUpdate");
   foreach(string path in paths){foreach(var text in home.Find(path).GetComponentsInChildren<TextMeshProUGUI>(true)){text.ForceMeshUpdate();Req(text.font.HasCharacters(text.text)&&!text.isTextOverflowing,"글리프/잘림 "+text.name);}}
   Canvas.ForceUpdateCanvases();cam.Render();foreach(string path in new[]{paths[0],paths[1],paths[3],paths[4]}){var r=(RectTransform)home.Find(path);var hit=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(cam,r.TransformPoint(r.rect.center))},hit);Req(hit.Count>0&&hit[0].gameObject.transform.IsChildOf(r),"실제 Raycast "+path);}
   RenderTexture.active=rt;tex=new Texture2D(1080,h,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1080,h),0,0);tex.Apply();File.WriteAllBytes("Validation/home_menu_mesh_"+state+"_"+h+".png",tex.EncodeToPNG());results.Add("PASS "+h+" "+state+" SafeArea/간격/TMP/아이콘/터치/BEST");
  }finally{canvas.renderMode=mode;canvas.worldCamera=camera;cam.targetTexture=target;cam.orthographic=ortho;cam.orthographicSize=size;RenderTexture.active=active;safe.anchorMin=min;safe.anchorMax=max;sa.enabled=enabled;if(tex!=null)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}
 }
 static Rect World(RectTransform r){var c=new Vector3[4];r.GetWorldCorners(c);return Rect.MinMaxRect(c[0].x,c[0].y,c[2].x,c[2].y);}static bool Inside(Rect a,Rect b)=>b.xMin>=a.xMin-.1f&&b.yMin>=a.yMin-.1f&&b.xMax<=a.xMax+.1f&&b.yMax<=a.yMax+.1f;
 static void Req(bool b,string m){count++;if(!b)throw new Exception(m);}static void Log(string m,string s,LogType t){if(t==LogType.Warning)warnings+=m+"\n";if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors+=m+"\n";}
 static void Finish(bool pass,string failure){EditorApplication.update-=Check;Application.logMessageReceived-=Log;if(session!=null)session.LeaveForHome();RunSaveStore.Delete();foreach(var k in keys){if(saved.TryGetValue(k,out int value))PlayerPrefs.SetInt(k,value);else PlayerPrefs.DeleteKey(k);}PlayerPrefs.Save();File.WriteAllText("Validation/home_menu_mesh_tests.txt",string.Join("\n",results)+"\nAssertions="+count+"\nWarnings="+warnings+"\nErrors="+errors+"\n"+(pass?"HOME_MENU_MESH_PASS":failure));EditorApplication.Exit(pass?0:1);}
}
